55	export type DiscountType = "pct" | "amt";
56	
57	export type CartItemInput = {
58	  productId: string;
59	  qty: number;
60	  disc: number;
61	  discType: DiscountType;
62	};
63	
64	export type CheckoutResult =
65	  | {
66	      success: true;
67	      invoiceNumber: string;
68	      transactionId: string;
69	      printJobs: KitchenPrintJobPayload[];
70	      receiptPrintJobs: KitchenPrintJobPayload[];
71	    }
72	  | { success: false; error: string };
73	
74	type CheckoutRpcRow = { transaction_id: string; invoice_number: string; already_existed: boolean };
75	
76	export async function checkout(
77	  businessId: string,
78	  cashierId: string,
79	  items: CartItemInput[],
80	  paymentMethod: string,
81	  received: number | null,
82	  orderDisc: number,
83	  orderDiscType: DiscountType,
84	  customerId: string | null = null,
85	  selfOrderIds: string[] = [],
86	  // Dibuat sekali di browser per penjualan (crypto.randomUUID()) dan dikirim
87	  // ulang apa adanya kalau ini retry dari antrian offline — RPC memakainya
88	  // untuk mengenali retry yang mengulang penjualan yang sebenarnya sudah
89	  // sukses (respons sebelumnya tidak sempat sampai ke browser), supaya tidak
90	  // membuat transaksi duplikat. Lihat src/hooks/use-offline-sync.ts.
91	  clientRef: string | null = null,
92	): Promise<CheckoutResult> {
93	  if (items.length === 0) {
94	    return { success: false, error: "Keranjang masih kosong." };
95	  }
96	
97	  const supabase = await createClient();
98	  const { data, error } = await supabase
99	    .rpc("checkout_transaction", {
100	      p_business_id: businessId,
101	      p_cashier_id: cashierId,
102	      p_items: items.map((i) => ({
103	        product_id: i.productId,
104	        qty: i.qty,
105	        disc: i.disc,
106	        disc_type: i.discType,
107	      })),
108	      p_payment_method: paymentMethod,
109	      p_received: received,
110	      p_order_disc: orderDisc,
111	      p_order_disc_type: orderDiscType,
112	      p_customer_id: customerId,
113	      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
114	      p_client_ref: clientRef,
115	    })
116	    .single();
117	
118	  if (error || !data) {
119	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
120	  }
121	
122	  const result = data as CheckoutRpcRow;
123	  let printJobs: KitchenPrintJobPayload[] = [];
124	  let receiptPrintJobs: KitchenPrintJobPayload[] = [];
125	
126	  // Retry offline yang ternyata sudah pernah sukses sebelumnya — jangan catat
127	  // aktivitas/cetak dapur dua kali untuk penjualan yang sama.
128	  if (!result.already_existed) {
129	    const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
130	
131	    // Tiga hal ini tidak saling bergantung — dulu dijalankan berurutan
132	    // (await satu-satu), menambah beberapa detik nyata ke waktu konfirmasi
133	    // pembayaran di jaringan mobile. Sekarang jalan bersamaan.
134	    const [, printJobsResult, receiptJobsResult] = await Promise.all([
135	      logActivity(
136	        supabase,
137	        businessId,
138	        "transaksi",
139	        "sukses",
140	        `Transaksi ${result.invoice_number}`,
141	        `${itemCount} item · ${paymentMethod}`,
142	      ),
143	      buildKitchenPrintJobsForItems(
144	        supabase,
145	        businessId,
146	        "Kasir",
147	        result.invoice_number,
148	        items.map((i) => ({ productId: i.productId, qty: i.qty })),
149	      ),
150	      buildReceiptPrintJobsForTransaction(supabase, businessId, result.transaction_id),
151	    ]);
152	    printJobs = printJobsResult;
153	    receiptPrintJobs = receiptJobsResult;
154	  }
155	
156	  return {
157	    success: true,
158	    invoiceNumber: result.invoice_number,
159	    transactionId: result.transaction_id,
160	    printJobs,
161	    receiptPrintJobs,
162	  };
163	}
