165	// Printer(s) flagged prints_receipt get the priced customer receipt
166	// automatically at checkout — no manual "Cetak Struk" click needed. Kept
167	// separate from printJobs (kitchen tickets) so callers can dispatch the
168	// receipt first: same physical printer sometimes handles both roles, and
169	// Bluetooth sockets don't like concurrent jobs to the same device.
170	async function buildReceiptPrintJobsForTransaction(
171	  supabase: Awaited<ReturnType<typeof createClient>>,
172	  businessId: string,
173	  transactionId: string,
174	): Promise<KitchenPrintJobPayload[]> {
175	  // Query printer dan bangun buffer struk tidak saling bergantung — buffer
176	  // tidak butuh daftar printer sama sekali. Jalankan bersamaan, baru buang
177	  // hasil buffer kalau ternyata tidak ada printer prints_receipt.
178	  const [{ data: printers }, bufferResult] = await Promise.all([
179	    supabase
180	      .from("kitchen_printers")
181	      .select("name, connection_type, address")
182	      .eq("business_id", businessId)
183	      .eq("prints_receipt", true)
184	      .not("address", "is", null),
185	    buildReceiptBuffer(supabase, businessId, transactionId),
186	  ]);
187	
188	  if (!printers || printers.length === 0) return [];
189	  if (!bufferResult.success) return [];
190	
191	  const bytesBase64 = bufferResult.buffer.toString("base64");
192	  return printers.map((p) => ({
193	    printerName: p.name,
194	    address: p.address as string,
195	    connectionType: p.connection_type as "lan" | "bluetooth",
196	    bytesBase64,
197	  }));
198	}
199	
200	async function buildKitchenPrintJobsForItems(
201	  supabase: Awaited<ReturnType<typeof createClient>>,
202	  businessId: string,
203	  source: string,
204	  label: string,
205	  items: { productId: string; qty: number; note?: string | null }[],
206	): Promise<KitchenPrintJobPayload[]> {
207	  const productIds = Array.from(new Set(items.map((i) => i.productId)));
208	  const { data: products } = await supabase
209	    .from("products")
210	    .select("id, name, category")
211	    .in("id", productIds);
212	  const productMap = new Map((products ?? []).map((p) => [p.id, p]));
213	
214	  return buildKitchenPrintJobs(supabase, businessId, {
215	    source,
216	    label,
217	    items: items.map((i) => ({
218	      name: productMap.get(i.productId)?.name ?? "Item",
219	      category: productMap.get(i.productId)?.category ?? null,
220	      qty: i.qty,
221	      note: i.note,
222	    })),
223	  }).catch(() => []);
224	}
