226	export async function logKitchenPrintFailures(
227	  businessId: string,
228	  failures: { printer: string; error: string }[],
229	) {
230	  if (failures.length === 0) return;
231	  const supabase = await createClient();
232	  await logActivity(
233	    supabase,
234	    businessId,
235	    "sistem",
236	    "warning",
237	    `Gagal cetak ke dapur: ${failures.map((f) => f.printer).join(", ")}`,
238	    failures.map((f) => f.error).join(" · "),
239	  );
240	}
