256	export type BuildTestPrintJobResult =
257	  | { success: true; job: KitchenPrintJobPayload }
258	  | { success: false; error: string };
259	
260	// One ticket, sent straight at a single chosen printer — no category
261	// routing, unlike buildKitchenPrintJobs (that one fans a real order out to
262	// every matching station). Used by the POS "Tes Cetak" screen.
263	export async function buildTestPrintJob(
264	  businessId: string,
265	  printerId: string,
266	): Promise<BuildTestPrintJobResult> {
267	  const supabase = await createClient();
268	  const { data: printer } = await supabase
269	    .from("kitchen_printers")
270	    .select("name, connection_type, address")
271	    .eq("id", printerId)
272	    .eq("business_id", businessId)
273	    .maybeSingle();
274	
275	  if (!printer) {
276	    return { success: false, error: "Printer tidak ditemukan." };
277	  }
278	  if (!printer.address) {
279	    return { success: false, error: "Printer ini belum diatur alamat/perangkatnya." };
280	  }
281	
282	  const buffer = buildKitchenTicket({
283	    station: printer.name,
284	    source: "Tes Cetak",
285	    label: new Date().toLocaleString("id-ID"),
286	    items: [{ name: "Ini tes cetak dari Kasirku", qty: 1 }],
287	  });
288	
289	  return {
290	    success: true,
291	    job: {
292	      printerName: printer.name,
293	      address: printer.address,
294	      connectionType: printer.connection_type as "lan" | "bluetooth",
295	      bytesBase64: buffer.toString("base64"),
296	    },
297	  };
298	}
