345	export async function closeShift(
346	  businessId: string,
347	  shiftId: string,
348	  closingCash: number,
349	  closeNotes: string,
350	): Promise<CloseShiftResult> {
351	  const supabase = await createClient();
352	  const { data, error } = await supabase
353	    .rpc("close_shift", {
354	      p_shift_id: shiftId,
355	      p_closing_cash: closingCash,
356	      p_close_notes: closeNotes || null,
357	    })
358	    .single();
359	
360	  if (error || !data) {
361	    return { success: false, error: error?.message ?? "Gagal menutup shift." };
362	  }
363	
364	  const summary = data as CloseShiftSummary;
365	  await logActivity(
366	    supabase,
367	    businessId,
368	    "sistem",
369	    summary.difference === 0 ? "info" : "warning",
370	    "Shift ditutup",
371	    `Penjualan Rp${summary.total_sales.toLocaleString("id-ID")} · ${summary.tx_count} transaksi · selisih Rp${summary.difference.toLocaleString("id-ID")}`,
372	  );
373	  return { success: true, summary };
374	}
