424	export async function saveOpenBill(
425	  businessId: string,
426	  billId: string | null,
427	  label: string,
428	  items: OpenBillItemInput[],
429	): Promise<SaveOpenBillResult> {
430	  const trimmed = label.trim();
431	  if (!trimmed) {
432	    return { success: false, error: "Nama bon wajib diisi." };
433	  }
434	  if (items.length === 0) {
435	    return { success: false, error: "Keranjang masih kosong." };
436	  }
437	
438	  const supabase = await createClient();
439	
440	  if (billId) {
441	    const { error } = await supabase
442	      .from("open_bills")
443	      .update({ label: trimmed, items, updated_at: new Date().toISOString() })
444	      .eq("id", billId)
445	      .eq("business_id", businessId);
446	    if (error) {
447	      return { success: false, error: error.message };
448	    }
449	    revalidatePath(`/business/${businessId}/pos`);
450	    return { success: true, billId };
451	  }
452	
453	  const { data, error } = await supabase
454	    .from("open_bills")
455	    .insert({ business_id: businessId, label: trimmed, items })
456	    .select("id")
457	    .single();
458	
459	  if (error || !data) {
460	    return { success: false, error: error?.message ?? "Gagal menyimpan bon." };
461	  }
462	
463	  await logActivity(
464	    supabase,
465	    businessId,
466	    "transaksi",
467	    "info",
468	    `Open Bill dibuat: ${trimmed}`,
469	    `${items.length} jenis item`,
470	  );
471	  revalidatePath(`/business/${businessId}/pos`);
472	  return { success: true, billId: data.id };
473	}
