517	// Sumber tunggal data katalog POS (produk/open bill/customer/metode bayar
518	// custom) — dipakai baik untuk render server pertama kali (pos/page.tsx)
519	// maupun refresh di background dari client (pos-screen.tsx, lihat
520	// pos-cache.ts). Sengaja tidak termasuk self_orders — itu sudah punya jalur
521	// polling sendiri (getSelfOrders di bawah).
522	export async function getPosCatalog(businessId: string): Promise<PosCatalog> {
523	  const supabase = await createClient();
524	
525	  const [{ data: products }, { data: openBillRows }, { data: customers }, { data: customPaymentMethodRows }] =
526	    await Promise.all([
527	      supabase
528	        .from("products")
529	        .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
530	        .eq("business_id", businessId)
531	        .is("deleted_at", null)
532	        .order("name", { ascending: true }),
533	      supabase
534	        .from("open_bills")
535	        .select("id, label, items, updated_at")
536	        .eq("business_id", businessId)
537	        .order("updated_at", { ascending: false }),
538	      supabase
539	        .from("customers")
540	        .select("id, name, phone")
541	        .eq("business_id", businessId)
542	        .is("deleted_at", null)
543	        .order("name", { ascending: true }),
544	      supabase
545	        .from("custom_payment_methods")
546	        .select("name")
547	        .eq("business_id", businessId)
548	        .order("name", { ascending: true }),
549	    ]);
550	
551	  return {
552	    products: (products ?? []) as PosProduct[],
553	    openBills: (openBillRows ?? []) as unknown as PosOpenBill[],
554	    customers: customers ?? [],
555	    customPaymentMethods: (customPaymentMethodRows ?? []).map((m) => m.name),
556	  };
557	}
