559	export type SelfOrderPayload = {
560	  id: string;
561	  status: "baru" | "diproses";
562	  createdAt: string;
563	  tableName: string;
564	  items: { productId: string | null; name: string; qty: number; price: number; note: string | null }[];
565	};
566	
567	// Dipakai oleh polling badge order masuk di pos-screen.tsx — dulu polling
568	// itu panggil router.refresh() tiap 15 detik, yang re-render SELURUH
569	// halaman POS (produk, open bill, customer, dst ikut di-fetch ulang).
570	// Action ini cuma ambil self_orders sendirian, jauh lebih ringan.
571	export async function getSelfOrders(businessId: string): Promise<SelfOrderPayload[]> {
572	  const supabase = await createClient();
573	  const { data } = await supabase
574	    .from("self_orders")
575	    .select(
576	      "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
577	    )
578	    .eq("business_id", businessId)
579	    .neq("status", "selesai")
580	    .order("created_at", { ascending: true });
581	
582	  return (
583	    data as unknown as {
584	      id: string;
585	      status: "baru" | "diproses";
586	      created_at: string;
587	      tables: { name: string } | null;
588	      self_order_items: { product_id: string | null; name: string; qty: number; price: number; note: string | null }[];
589	    }[]
590	    ?? []
591	  ).map((o) => ({
592	    id: o.id,
593	    status: o.status,
594	    createdAt: o.created_at,
595	    tableName: o.tables?.name ?? "Meja terhapus",
596	    items: o.self_order_items.map((i) => ({
597	      productId: i.product_id,
598	      name: i.name,
599	      qty: i.qty,
600	      price: i.price,
601	      note: i.note,
602	    })),
603	  }));
604	}
605	
606	export async function updateSelfOrderStatus(
607	  businessId: string,
608	  orderId: string,
609	  status: "diproses" | "selesai",
610	): Promise<{ success: boolean; error?: string; printJobs?: KitchenPrintJobPayload[] }> {
611	  const supabase = await createClient();
612	  const { data, error } = await supabase
613	    .from("self_orders")
614	    .update({ status })
615	    .eq("id", orderId)
616	    .eq("business_id", businessId)
617	    .select("tables(name)")
618	    .single();
619	
620	  if (error) {
621	    return { success: false, error: error.message };
622	  }
623	
624	  const tableName =
625	    (data as unknown as { tables: { name: string } | null }).tables?.name ?? "Meja terhapus";
626	  await logActivity(
627	    supabase,
628	    businessId,
629	    "transaksi",
630	    "info",
631	    `Pesanan ${tableName} → ${status}`,
632	  );
633	
634	  let printJobs: KitchenPrintJobPayload[] = [];
635	
636	  if (status === "diproses") {
637	    const { data: orderItems } = await supabase
