      product_id: i.productId,
      name: i.name,
      price: i.price,
      qty: i.qty,
      disc: i.disc,
      disc_type: i.discType,
    })),
  );
  setBonSaving(false);

  if (!result.success) {
    setBonError(result.error);
    return;
  }

  setCart([]);
  setCartOrderIds([]);
  setOrderDisc(0);
  setOrderDiscType("pct");
  setActiveBill(null);
  setSaveBonOpen(false);
