const activePromo = useMemo<DiscountRule | null>(() => {
  const today = new Date().toISOString().slice(0, 10);
  return (
    discountRules.find(
      (r) =>
        r.type === "promo" &&
        r.active &&
        (!r.valid_from || r.valid_from <= today) &&
        (!r.valid_until || r.valid_until >= today),
    ) ?? null
  );
}, [discountRules]);

