1	-- Perbarui checkout_transaction agar membaca field "note" opsional dari
2	-- setiap elemen p_items dan menyimpannya ke transaction_items.note.
3	-- transaction_items.note sudah ada sejak migrasi awal — hanya INSERT-nya
4	-- yang sekarang juga mengisi kolom itu.
5	-- Signature fungsi tidak berubah; GRANT tidak perlu diulang.
6	
7	drop function if exists public.checkout_transaction(
8	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[], uuid
9	);
10	
11	create or replace function public.checkout_transaction(
12	  p_business_id    uuid,
13	  p_cashier_id     uuid,
14	  p_items          jsonb,   -- array of {product_id, qty, disc, disc_type, note?}
15	  p_payment_method text,
16	  p_received       numeric  default null,
17	  p_order_disc     numeric  default 0,
18	  p_order_disc_type text    default 'pct',
19	  p_customer_id    uuid     default null,
20	  p_self_order_ids uuid[]   default null,
21	  p_client_ref     uuid     default null
22	)
23	returns table (transaction_id uuid, invoice_number text, already_existed boolean)
24	language plpgsql
25	security definer
26	set search_path = ''
27	as $$
28	declare
29	  v_business         record;
30	  v_invoice_number   text;
31	  v_seq              int;
32	  v_subtotal_raw     numeric(12, 2) := 0;
33	  v_total_item_disc  numeric(12, 2) := 0;
34	  v_order_disc_amt   numeric(12, 2) := 0;
35	  v_subtotal         numeric(12, 2);
36	  v_service          numeric(12, 2) := 0;
37	  v_tax              numeric(12, 2) := 0;
38	  v_total            numeric(12, 2);
39	  v_total_cost       numeric(12, 2) := 0;
40	  v_transaction_id   uuid;
41	  v_item             jsonb;
42	  v_qty              numeric(12, 2);
43	  v_product_id       uuid;
44	  v_product          record;
45	  v_line_gross       numeric(12, 2);
46	  v_disc             numeric(12, 2);
47	  v_disc_type        text;
48	  v_item_disc        numeric(12, 2);
49	  v_note             text;
50	  v_change           numeric(12, 2);
51	  v_shift_id         uuid;
52	  v_recipe           record;
53	  v_table_id         uuid;
54	  v_journal_lines    jsonb;
55	begin
56	  if not private.owns_business(p_business_id) then
57	    raise exception 'not authorized';
58	  end if;
59	
60	  if p_client_ref is not null then
61	    select t.id, t.invoice_number into v_transaction_id, v_invoice_number
62	    from public.transactions t
63	    where t.business_id = p_business_id and t.client_ref = p_client_ref;
64	
65	    if found then
66	      return query select v_transaction_id, v_invoice_number, true;
67	      return;
68	    end if;
69	  end if;
70	
71	  if not exists (
72	    select 1 from public.cashiers c
73	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
74	  ) then
75	    raise exception 'invalid cashier';
76	  end if;
77	
78	  if p_customer_id is not null and not exists (
79	    select 1 from public.customers c
80	    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
81	  ) then
82	    raise exception 'invalid customer';
83	  end if;
84	
85	  if p_self_order_ids is not null and exists (
86	    select 1 from public.self_orders so
87	    where so.id = any(p_self_order_ids) and so.business_id <> p_business_id
88	  ) then
89	    raise exception 'invalid self order';
90	  end if;
91	
92	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
93	    raise exception 'payment method required';
94	  end if;
95	
96	  if p_items is null or jsonb_array_length(p_items) = 0 then
97	    raise exception 'cart is empty';
98	  end if;
99	
100	  if p_order_disc_type not in ('pct', 'amt') then
101	    raise exception 'invalid order discount type';
102	  end if;
103	
104	  if p_order_disc is null or p_order_disc < 0
105	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
106	    raise exception 'invalid order discount';
107	  end if;
108	
109	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
110	  into v_business
111	  from public.businesses b
112	  where b.id = p_business_id;
113	
114	  select id into v_shift_id
115	  from public.shifts
116	  where business_id = p_business_id and closed_at is null
117	  limit 1;
118	
119	  if v_shift_id is null then
120	    raise exception 'no active shift — open a shift before selling';
121	  end if;
122	
123	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
124	    select table_id into v_table_id
125	    from public.self_orders
126	    where id = p_self_order_ids[1];
127	  end if;
128	
129	  select count(*) + 1 into v_seq
130	  from public.transactions t
131	  where t.business_id = p_business_id
132	    and t.date::date = current_date;
133	
134	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
135	
136	  insert into public.transactions (
137	    business_id, shift_id, cashier_id, customer_id, table_id, invoice_number, date,
138	    subtotal_raw, subtotal, total, total_cost, gross_profit, client_ref
139	  ) values (
140	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_table_id, v_invoice_number, now(),
141	    0, 0, 0, 0, 0, p_client_ref
142	  )
143	  returning id into v_transaction_id;
144	
145	  for v_item in select * from jsonb_array_elements(p_items)
146	  loop
147	    v_product_id := (v_item ->> 'product_id')::uuid;
148	    v_qty        := (v_item ->> 'qty')::numeric;
149	    v_disc       := coalesce((v_item ->> 'disc')::numeric, 0);
150	    v_disc_type  := coalesce(v_item ->> 'disc_type', 'pct');
151	    v_note       := v_item ->> 'note';
152	
153	    if v_qty is null or v_qty <= 0 then
154	      raise exception 'invalid quantity';
155	    end if;
156	
157	    if v_disc_type not in ('pct', 'amt') then
158	      raise exception 'invalid item discount type';
159	    end if;
160	
161	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
162	      raise exception 'invalid item discount';
163	    end if;
164	
165	    select * into v_product
166	    from public.products p
167	    where p.id = v_product_id
168	      and p.business_id = p_business_id
169	      and p.deleted_at is null;
170	
171	    if not found then
172	      raise exception 'product not found: %', v_product_id;
173	    end if;
174	
175	    v_line_gross := v_product.price * v_qty;
176	    v_item_disc  := case v_disc_type
177	      when 'pct' then round(v_line_gross * v_disc / 100)
178	      else least(v_disc * v_qty, v_line_gross)
179	    end;
180	
181	    insert into public.transaction_items (
182	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type, note
183	    ) values (
184	      v_transaction_id, v_product.id, v_product.name, v_product.category,
185	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type, v_note
186	    );
187	
188	    update public.products
189	    set stock = greatest(0, stock - v_qty)
190	    where id = v_product_id;
191	
192	    for v_recipe in
193	      select pr.ingredient_id, pr.qty as recipe_qty
194	      from public.product_recipes pr
195	      where pr.product_id = v_product_id and pr.ingredient_id is not null
196	    loop
197	      insert into public.transaction_ingredient_consumption (
198	        transaction_id, ingredient_id, qty
199	      ) values (
200	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
201	      );
202	
203	      update public.ingredients
204	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
205	      where id = v_recipe.ingredient_id;
206	    end loop;
207	
208	    v_subtotal_raw    := v_subtotal_raw + v_line_gross;
209	    v_total_item_disc := v_total_item_disc + v_item_disc;
210	    v_total_cost      := v_total_cost + v_product.cost * v_qty;
211	  end loop;
212	
213	  v_order_disc_amt := case p_order_disc_type
214	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
215	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
216	  end;
217	
218	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
219	
220	  if v_business.service_enabled then
221	    v_service := round(v_subtotal * v_business.service_rate / 100);
222	  end if;
223	
224	  if v_business.tax_enabled then
225	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
226	  end if;
227	
228	  v_total := v_subtotal + v_service + v_tax;
229	
230	  update public.transactions
231	  set subtotal_raw   = v_subtotal_raw,
232	      subtotal       = v_subtotal,
233	      total_item_disc = v_total_item_disc,
234	      order_disc_amt = v_order_disc_amt,
235	      service        = v_service,
236	      tax            = v_tax,
237	      total          = v_total,
238	      total_cost     = v_total_cost,
239	      gross_profit   = v_subtotal - v_total_cost
240	  where id = v_transaction_id;
241	
242	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
243	
244	  insert into public.transaction_payments (
245	    transaction_id, method, amount, received, change
246	  ) values (
247	    v_transaction_id, p_payment_method, v_total, p_received, v_change
248	  );
249	
250	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
251	    update public.self_orders
252	    set status = 'selesai'
253	    where id = any(p_self_order_ids)
254	      and business_id = p_business_id
255	      and status <> 'selesai';
256	  end if;
257	
258	  v_journal_lines := '[]'::jsonb;
259	  if v_total > 0 then
260	    v_journal_lines := v_journal_lines || jsonb_build_array(
261	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
262	      jsonb_build_object('account_code', '4-001', 'debit', 0, 'credit', v_subtotal + v_service)
263	    );
264	    if v_tax > 0 then
265	      v_journal_lines := v_journal_lines || jsonb_build_array(
266	        jsonb_build_object('account_code', '2-200', 'debit', 0, 'credit', v_tax)
267	      );
268	    end if;
269	  end if;
270	  if v_total_cost > 0 then
271	    v_journal_lines := v_journal_lines || jsonb_build_array(
272	      jsonb_build_object('account_code', '5-001', 'debit', v_total_cost, 'credit', 0),
273	      jsonb_build_object('account_code', '1-200', 'debit', 0, 'credit', v_total_cost)
274	    );
275	  end if;
276	  if jsonb_array_length(v_journal_lines) >= 2 then
277	    perform private.post_journal(
278	      p_business_id, now(), 'Penjualan ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
279	    );
280	  end if;
281	
282	  return query select v_transaction_id, v_invoice_number, false;
283	end;
284	$$;
285	
286	grant execute on function public.checkout_transaction(
287	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[], uuid
288	) to authenticated;
