import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { importTransactions } from "./actions";
import { TransactionActions } from "./transaction-actions";

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export default async function TransactionsPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: transactions } = await supabase
    .from("transactions")
    .select(
      "id, invoice_number, date, total, voided, cashiers!transactions_cashier_id_fkey(name), transaction_payments(method)",
    )
    .eq("business_id", businessId)
    .order("date", { ascending: false })
    .limit(50);

  const boundImportTransactions = importTransactions.bind(null, businessId);

  return (
    <div className="w-full max-w-2xl">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-lg font-bold text-zinc-900">
              Riwayat Transaksi — {business.name}
            </h1>
            <p className="mt-1 text-sm text-zinc-500">50 transaksi terbaru.</p>
          </div>
          <TransactionActions businessId={businessId} importAction={boundImportTransactions} />
        </div>

        <div className="mt-6 space-y-2">
          {transactions && transactions.length > 0 ? (
            transactions.map((t) => (
              <Link
                key={t.id}
                href={`/business/${businessId}/transactions/${t.id}`}
                className="block rounded-xl border border-zinc-200 bg-white px-4 py-3 transition-colors hover:border-brand-300"
              >
                <div className="flex items-center justify-between">
                  <p className="text-xs font-semibold text-zinc-900">{t.invoice_number}</p>
                  {t.voided ? (
                    <span className="rounded-full bg-red-50 px-2 py-0.5 text-[10px] font-medium text-red-600">
                      Dibatalkan
                    </span>
                  ) : (
                    <p className="text-sm font-semibold text-zinc-900">
                      {formatRupiah(Number(t.total))}
                    </p>
                  )}
                </div>
                <p className="mt-1 text-xs text-zinc-500">
                  {formatDateTime(t.date)} ·{" "}
                  {(t.cashiers as unknown as { name: string } | null)?.name ?? "—"} ·{" "}
                  {(t.transaction_payments as { method: string }[] | null)?.map((p) => p.method).join(" + ") || "—"}
                </p>
              </Link>
            ))
          ) : (
            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
              Belum ada transaksi.
            </p>
          )}
        </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { checkout } from "@/app/business/[businessId]/pos/actions";
import { checkoutTicket } from "@/app/business/[businessId]/pos/ticket-actions";
import {
  discardPending,
  enqueueSale,
  listPending,
  markError,
  markSynced,
  markSyncing,
  type PendingSale,
} from "@/lib/offline-queue";
import { dispatchReceiptThenKitchenJobs } from "@/lib/dispatch-print-jobs";
import type { KitchenPrintJobPayload } from "@/lib/kitchen-print";

const SYNC_INTERVAL_MS = 20000;

// Dipakai di pos-screen.tsx & ticket-pos-screen.tsx. Melacak status
// online/offline browser, menyimpan/membaca antrian penjualan tertunda dari
// IndexedDB, dan mencoba sinkronkan ulang otomatis begitu koneksi kembali.
// Lihat rencana di plan file untuk kenapa desainnya begini — intinya: retry
// harus berurutan (bukan paralel) supaya konflik nomor tiket fisik
// terdeteksi satu-satu, dan idempotency (clientRef) di server yang menjamin
// retry yang mengulang penjualan yang sebenarnya sudah sukses tidak
// membuat transaksi duplikat.
export function useOfflineSync(businessId: string) {
  const [isOnline, setIsOnline] = useState(
    () => typeof navigator === "undefined" || navigator.onLine,
  );
  const [pending, setPending] = useState<PendingSale[]>([]);
  const syncingRef = useRef(false);

  const refresh = useCallback(async () => {
    const rows = await listPending(businessId);
    setPending(rows);
    return rows;
  }, [businessId]);

  const syncNow = useCallback(async () => {
    if (syncingRef.current) return;
    if (typeof navigator !== "undefined" && !navigator.onLine) return;
    syncingRef.current = true;
    try {
      const rows = await refresh();
      for (const sale of rows) {
        // Sudah gagal karena alasan bisnis (bukan jaringan) sebelumnya —
        // butuh tinjauan manual, jangan di-retry otomatis terus-menerus.
        if (sale.status === "error") continue;

        await markSyncing(sale);
        try {
          const result =
            sale.kind === "retail"
              ? await checkout(
                  sale.businessId,
                  sale.payload.cashierId,
                  sale.payload.items,
                  sale.payload.payments,
                  sale.payload.orderDisc,
                  sale.payload.orderDiscType,
                  sale.payload.customerId,
                  sale.payload.selfOrderIds,
                  sale.clientRef,
                )
              : await checkoutTicket(
                  sale.businessId,
                  sale.payload.cashierId,
                  sale.payload.items,
                  sale.payload.paymentMethod,
                  sale.payload.received,
                  sale.payload.memberId,
                  sale.clientRef,
                );

          if (result.success) {
            await markSynced(sale.clientRef);
            // Only the "retail" checkout() path returns printJobs —
            // checkoutTicket() doesn't do kitchen printing at all.
            if (sale.kind === "retail") {
              const { printJobs, receiptPrintJobs } = result as unknown as {
                printJobs: KitchenPrintJobPayload[];
                receiptPrintJobs: KitchenPrintJobPayload[];
              };
              void dispatchReceiptThenKitchenJobs(sale.businessId, receiptPrintJobs, printJobs);
            }
          } else {
            await markError(sale, result.error);
          }
        } catch {
          // Masih gagal jaringan (timeout/koneksi putus lagi) — kembalikan
          // ke "pending", coba lagi di siklus sync berikutnya.
          await enqueueSale({ ...sale, status: "pending" });
        }
      }
    } finally {
      syncingRef.current = false;
      await refresh();
    }
  }, [refresh]);

  const discard = useCallback(
    async (clientRef: string) => {
      await discardPending(clientRef);
      await refresh();
    },
    [refresh],
  );

  useEffect(() => {
    listPending(businessId).then(setPending);

    function handleOnline() {
      setIsOnline(true);
      void syncNow();
    }
    function handleOffline() {
      setIsOnline(false);
    }

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, [businessId, syncNow]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (pending.length > 0) void syncNow();
    }, SYNC_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [pending.length, syncNow]);

  return { isOnline, pending, syncNow, discard };
}

import { idbDelete, idbGetAllByBusiness, idbPut } from "@/lib/offline-db";
import type { DiscountType, TenderInput } from "@/app/business/[businessId]/pos/actions";
import type { TicketCartItemInput } from "@/app/business/[businessId]/pos/ticket-actions";

export type PendingSaleStatus = "pending" | "syncing" | "error";

export type PendingRetailSale = {
  clientRef: string;
  businessId: string;
  kind: "retail";
  createdAt: string;
  status: PendingSaleStatus;
  errorMessage?: string;
  payload: {
    cashierId: string;
    items: { productId: string; qty: number; disc: number; discType: DiscountType; note?: string | null }[];
    payments: TenderInput[];
    orderDisc: number;
    orderDiscType: DiscountType;
    customerId: string | null;
    selfOrderIds: string[];
  };
};

export type PendingTicketSale = {
  clientRef: string;
  businessId: string;
  kind: "ticket";
  createdAt: string;
  status: PendingSaleStatus;
  errorMessage?: string;
  payload: {
    cashierId: string;
    items: TicketCartItemInput[];
    paymentMethod: string;
    received: number | null;
    memberId: string | null;
  };
};

export type PendingSale = PendingRetailSale | PendingTicketSale;

export async function enqueueSale(sale: PendingSale): Promise<void> {
  await idbPut(sale);
}

export async function listPending(businessId: string): Promise<PendingSale[]> {
  const rows = await idbGetAllByBusiness<PendingSale>(businessId);
  return rows.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

export async function markSyncing(sale: PendingSale): Promise<void> {
  await idbPut({ ...sale, status: "syncing", errorMessage: undefined });
}

export async function markSynced(clientRef: string): Promise<void> {
  await idbDelete(clientRef);
}

export async function markError(sale: PendingSale, message: string): Promise<void> {
  await idbPut({ ...sale, status: "error", errorMessage: message });
}

export async function discardPending(clientRef: string): Promise<void> {
  await idbDelete(clientRef);
}

// Stok server-side belum tahu apa-apa soal penjualan yang masih di antrian
// offline — kurangi tampilan stok kasir secara lokal supaya tidak menjual
// melebihi yang sebenarnya tersisa, sampai antrian ini tersinkron.
export function pendingStockDeltas(pending: PendingSale[]): Record<string, number> {
  const deltas: Record<string, number> = {};
  for (const sale of pending) {
    if (sale.kind !== "retail") continue;
    for (const item of sale.payload.items) {
      deltas[item.productId] = (deltas[item.productId] ?? 0) + item.qty;
    }
  }
  return deltas;
}

