export type ReceiptTicketInput = {
  businessName: string;
  invoiceNumber: string;
  date: string;
  cashierName: string;
  voided: boolean;
  items: ReceiptItem[];
  subtotal: number;
  itemDiscount: number;
  orderDiscount: number;
  service: number;
  tax: number;
  total: number;
  payments: ReceiptPayment[];
};

function formatRp(value: number): string {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

// Full priced customer receipt (struk kasir) — distinct from
// buildKitchenTicket, which deliberately omits prices for the kitchen/bar
// copy. Sent through the same native LAN/Bluetooth plugin as kitchen
// tickets, since Android's OS-level print framework generally can't drive
// cheap ESC/POS thermal printers (see dispatch-print-jobs.ts).
export function buildReceiptTicket(input: ReceiptTicketInput): Buffer {
  const chunks: Buffer[] = [];
  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
  const divider = () => text("-".repeat(RECEIPT_WIDTH));

  push([ESC, 0x40]); // initialize

  push([ESC, 0x61, 0x01]); // center align
  text(input.businessName.toUpperCase());
  if (input.voided) {
    push([ESC, 0x45, 0x01]);
    text("*** DIBATALKAN ***");
    push([ESC, 0x45, 0x00]);
  }
  push([ESC, 0x61, 0x00]); // left align

  divider();
  text(padLine("No.", input.invoiceNumber));
  text(padLine("Tanggal", input.date));
  text(padLine("Kasir", input.cashierName));

  divider();
  for (const item of input.items) {
    text(truncate(item.name));
    text(padLine(`  ${formatQty(item.qty)}x${formatRp(item.price)}`, formatRp(item.price * item.qty)));
  }

  divider();
  text(padLine("Subtotal", formatRp(input.subtotal)));
  if (input.itemDiscount > 0) text(padLine("Diskon item", `-${formatRp(input.itemDiscount)}`));
  if (input.orderDiscount > 0) text(padLine("Diskon order", `-${formatRp(input.orderDiscount)}`));
  if (input.service > 0) text(padLine("Layanan", formatRp(input.service)));
  if (input.tax > 0) text(padLine("PPN", formatRp(input.tax)));
  push([ESC, 0x45, 0x01]);
  text(padLine("TOTAL", formatRp(input.total)));
  push([ESC, 0x45, 0x00]);

  divider();
  for (const p of input.payments) {
    text(padLine(p.method, formatRp(p.amount)));
    if (p.received !== null) text(padLine("Diterima", formatRp(p.received)));
    if (p.change !== null && p.change > 0) text(padLine("Kembalian", formatRp(p.change)));
  }

  push([ESC, 0x61, 0x01]); // center align
  text("");
  text("Terima kasih!");
  text("");
  text("");
  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed

  return Buffer.concat(chunks);
}

export type SettlementByMethod = { method: string; amount: number };

export type SettlementTicketInput = {
  businessName: string;
  periodLabel: string;
  byMethod: SettlementByMethod[];
  totalSales: number;
  txCount: number;
  voidCount: number;
};

import type { SupabaseClient } from "@supabase/supabase-js";
import { buildReceiptTicket } from "./escpos";

export type BuildReceiptBufferResult =
  | { success: true; buffer: Buffer }
  | { success: false; error: string };

// Shared by the automatic "print receipt on checkout" path (checkout()) and
// the manual "Cetak ke <printer>" button on the receipt page — both just
// need the priced ticket bytes for a transaction, independent of which
// printer it ends up going to.
export async function buildReceiptBuffer(
  supabase: SupabaseClient,
  businessId: string,
  transactionId: string,
): Promise<BuildReceiptBufferResult> {
  const [{ data: business }, { data: transaction }, { data: items }, { data: payments }] =
    await Promise.all([
      supabase.from("businesses").select("name").eq("id", businessId).single(),
      supabase
        .from("transactions")
        .select(
          "invoice_number, date, subtotal_raw, service, tax, total_item_disc, order_disc_amt, total, voided, cashiers!transactions_cashier_id_fkey(name)",
        )
        .eq("id", transactionId)
        .eq("business_id", businessId)
        .single(),
      supabase
        .from("transaction_items")
        .select("id, name, price, qty")
        .eq("transaction_id", transactionId)
        .order("id", { ascending: true }),
      supabase
        .from("transaction_payments")
        .select("method, amount, received, change")
        .eq("transaction_id", transactionId),
    ]);

  if (!business || !transaction) {
    return { success: false, error: "Transaksi tidak ditemukan." };
  }

  const buffer = buildReceiptTicket({
    businessName: business.name,
    invoiceNumber: transaction.invoice_number,
    date: new Date(transaction.date).toLocaleString("id-ID", { dateStyle: "medium", timeStyle: "short" }),
    cashierName: (transaction.cashiers as unknown as { name: string } | null)?.name ?? "—",
    voided: transaction.voided,
    items: (items ?? []).map((i) => ({ name: i.name, qty: Number(i.qty), price: Number(i.price) })),
    subtotal: Number(transaction.subtotal_raw),
    itemDiscount: Number(transaction.total_item_disc),
    orderDiscount: Number(transaction.order_disc_amt),
    service: Number(transaction.service),
    tax: Number(transaction.tax),
    total: Number(transaction.total),
    payments: (payments ?? []).map((p) => ({
      method: p.method,
      amount: Number(p.amount),
      received: p.received === null ? null : Number(p.received),
      change: p.change === null ? null : Number(p.change),
    })),
  });

  return { success: true, buffer };
}

import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import PrintButton from "./print-button";

function formatRupiah(value: number) {
  return `Rp${value.toLocaleString("id-ID")}`;
}

function formatDateTime(iso: string) {
  return new Date(iso).toLocaleString("id-ID", {
    dateStyle: "medium",
    timeStyle: "short",
  });
}

export default async function ReceiptPage({
  params,
}: {
  params: Promise<{ businessId: string; transactionId: string }>;
}) {
  const { businessId, transactionId } = await params;
  const supabase = await createClient();

  // Keempat query tidak saling bergantung (semua cuma butuh businessId/
  // transactionId dari params) — dijalankan paralel, bukan berurutan,
  // supaya struk render lebih cepat begitu dibuka dari POS.
  const [{ data: business }, { data: transaction }, { data: items }, { data: payments }, { data: printers }] =
    await Promise.all([
      supabase.from("businesses").select("name").eq("id", businessId).single(),
      supabase
        .from("transactions")
        .select(
          "id, invoice_number, date, subtotal_raw, subtotal, service, tax, total_item_disc, order_disc_amt, total, voided, cashiers!transactions_cashier_id_fkey(name)",
        )
        .eq("id", transactionId)
        .eq("business_id", businessId)
        .single(),
      supabase
        .from("transaction_items")
        .select("id, name, price, qty")
        .eq("transaction_id", transactionId)
        .order("id", { ascending: true }),
      supabase
        .from("transaction_payments")
        .select("id, method, amount, received, change")
        .eq("transaction_id", transactionId),
      supabase
        .from("kitchen_printers")
        .select("id, name")
        .eq("business_id", businessId)
        .order("name", { ascending: true }),
    ]);

  if (!business || !transaction) {
    notFound();
  }

  return (
    <div className="w-full max-w-xs font-mono text-xs text-zinc-900 print:max-w-none">
        <div className="print:hidden">
          <PrintButton
            businessId={businessId}
            transactionId={transactionId}
            printers={printers ?? []}
          />
        </div>

        <div className="mt-4 rounded-xl bg-white shadow-sm p-5 print:mt-0 print:rounded-none print:border-0 print:p-0">
          <div className="text-center">
            <p className="text-sm font-bold uppercase">{business.name}</p>
            {transaction.voided && (
              <p className="mt-1 font-bold text-red-600">*** DIBATALKAN ***</p>
            )}
          </div>

          <div className="mt-3 border-t border-dashed border-zinc-300 pt-2">
            <div className="flex justify-between">
              <span>No.</span>
              <span>{transaction.invoice_number}</span>
            </div>
            <div className="flex justify-between">
              <span>Tanggal</span>
              <span>{formatDateTime(transaction.date)}</span>
            </div>
            <div className="flex justify-between">
              <span>Kasir</span>
              <span>
                {(transaction.cashiers as unknown as { name: string } | null)?.name ?? "—"}
              </span>
            </div>
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            {items?.map((item) => (
              <div key={item.id} className="flex justify-between gap-2">
                <span className="flex-1 truncate">
                  {item.name}
                  <span className="text-zinc-500">
                    {" "}
                    {item.qty}x{Number(item.price).toLocaleString("id-ID")}
                  </span>
                </span>
                <span className="shrink-0">
                  {formatRupiah(Number(item.price) * Number(item.qty))}
                </span>
              </div>
            ))}
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            <div className="flex justify-between">
              <span>Subtotal</span>
              <span>{formatRupiah(Number(transaction.subtotal_raw))}</span>
            </div>
            {Number(transaction.total_item_disc) > 0 && (
              <div className="flex justify-between">
                <span>Diskon item</span>
                <span>-{formatRupiah(Number(transaction.total_item_disc))}</span>
              </div>
            )}
            {Number(transaction.order_disc_amt) > 0 && (
              <div className="flex justify-between">
                <span>Diskon order</span>
                <span>-{formatRupiah(Number(transaction.order_disc_amt))}</span>
              </div>
            )}
            {Number(transaction.service) > 0 && (
              <div className="flex justify-between">
                <span>Layanan</span>
                <span>{formatRupiah(Number(transaction.service))}</span>
              </div>
            )}
            {Number(transaction.tax) > 0 && (
              <div className="flex justify-between">
                <span>PPN</span>
                <span>{formatRupiah(Number(transaction.tax))}</span>
              </div>
            )}
            <div className="flex justify-between border-t border-dashed border-zinc-300 pt-1 text-sm font-bold">
              <span>TOTAL</span>
              <span>{formatRupiah(Number(transaction.total))}</span>
            </div>
          </div>

          <div className="mt-2 space-y-1 border-t border-dashed border-zinc-300 pt-2">
            {payments?.map((p) => (
              <div key={p.id}>
                <div className="flex justify-between">
                  <span>{p.method}</span>
                  <span>{formatRupiah(Number(p.amount))}</span>
                </div>
                {p.received !== null && (
                  <div className="flex justify-between">
                    <span>Diterima</span>
                    <span>{formatRupiah(Number(p.received))}</span>
                  </div>
                )}
                {p.change !== null && Number(p.change) > 0 && (
                  <div className="flex justify-between">
                    <span>Kembalian</span>
                    <span>{formatRupiah(Number(p.change))}</span>
                  </div>
                )}
              </div>
            ))}
          </div>

          <p className="mt-4 border-t border-dashed border-zinc-300 pt-2 text-center">
            Terima kasih!
          </p>
        </div>
    </div>
  );
}

