          <span>02/08 12:00</span>
        </div>
        {s.show_cashier && (
          <div className="flex justify-between gap-1">
            <span>Kasir</span>
            <span>Andi</span>
          </div>
        )}
      </div>

      <div className="mt-1 border-t border-dashed border-zinc-300 pt-1 space-y-0.5">
        {items.map((item, i) => (
          <div key={i}>
